from math import gcd
from typing import Dict, List

def is_prime(n: int) -> bool:
    if n < 2:
        return False
    d = 2
    while d * d <= n:
        if n % d == 0:
            return False
        d += 1
    return True

def factorize(n: int) -> Dict[int, int]:
    factors: Dict[int, int] = {}
    d, m = 2, n
    while d * d <= m:
        while m % d == 0:
            factors[d] = factors.get(d, 0) + 1
            m //= d
        d += 1 if d == 2 else 2
    if m > 1:
        factors[m] = factors.get(m, 0) + 1
    return factors

def is_korselt(n: int) -> bool:
    """Decide whether n is a Carmichael number via Korselt's criterion."""
    if n < 2 or is_prime(n):
        return False                       # primes / units are excluded
    factors = factorize(n)
    if any(e > 1 for e in factors.values()):
        return False                       # not squarefree
    return all((n - 1) % (p - 1) == 0 for p in factors)  # (p-1)|(n-1)

from math import gcd
from functools import reduce
from typing import Dict, List

def factorize(n: int) -> Dict[int, int]:
    factors: Dict[int, int] = {}
    d, m = 2, n
    while d * d <= m:
        while m % d == 0:
            factors[d] = factors.get(d, 0) + 1
            m //= d
        d += 1 if d == 2 else 2
    if m > 1:
        factors[m] = factors.get(m, 0) + 1
    return factors

def lcm(a: int, b: int) -> int:
    return a // gcd(a, b) * b

def carmichael_lambda_squarefree(n: int) -> int:
    """lambda(n) = lcm of (p-1) over primes p | n (n assumed squarefree)."""
    primes: List[int] = list(factorize(n).keys())
    return reduce(lcm, (p - 1 for p in primes), 1)

def is_carmichael_via_lambda(n: int) -> bool:
    """n is Carmichael iff lambda(n) | (n-1) and n is squarefree composite."""
    factors = factorize(n)
    if len(factors) < 2 or any(e > 1 for e in factors.values()):
        return False
    return (n - 1) % carmichael_lambda_squarefree(n) == 0

from math import gcd

def multiplicative_order(a: int, m: int) -> int:
    """Least k >= 1 with a^k == 1 (mod m); requires gcd(a, m) == 1."""
    if gcd(a, m) != 1:
        raise ValueError("requires gcd(a, m) == 1")
    k, x = 1, a % m
    while x != 1:
        x = (x * a) % m
        k += 1
    return k

def primitive_root(p: int) -> int:
    """A primitive root g mod prime p, i.e. ord_p(g) = p - 1."""
    for g in range(2, p):
        if multiplicative_order(g, p) == p - 1:
            return g
    raise RuntimeError("p must be prime")
